import {svg,bounds,scale,axes,palette,text,legend,unique} from '../gallery-utils.js';
export function render({data,params:p}){unique(data,['category','component']);if(data.some(d=>d.value<0))throw Error('组成量不能为负');const b=bounds(p),cats=[...new Set(data.map(d=>d.category))],parts=[...new Set(data.map(d=>d.component))],colors=palette(p),y=scale([0,100],b.b,b.t),slot=(b.r-b.l)/cats.length;let s=axes(b,null,y,{...p,yLabel:p.yLabel+' (%)'});cats.forEach((cat,i)=>{const d=data.filter(d=>d.category===cat),total=d.reduce((a,v)=>a+v.value,0);if(total<=0)throw Error('类别 '+cat+' 的总量必须大于零');let start=0;parts.forEach((part,j)=>{const val=(d.find(d=>d.component===part)?.value||0)/total*100;const x=b.l+(i+.5)*slot-slot*p.barWidth/2;s+=`<rect x="${x}" y="${y(start+val)}" width="${slot*p.barWidth}" height="${y(start)-y(start+val)}" fill="${colors[j%colors.length]}"/>`;if(val>=8)s+=text(x+slot*p.barWidth/2,y(start+val/2)+4,val.toFixed(1)+'%','text-anchor="middle" fill="white"');start+=val;});s+=text(b.l+(i+.5)*slot,b.b+23,cat,'text-anchor="middle"');});return svg(p,s+legend(b,parts,colors));}